(() => {
 const M=XVA_MATH,m=x=>'£'+Number(x).toFixed(3)+'m',p=x=>(100*x).toFixed(2)+'%',a=(id,label,min,max,step,value,unit='£m')=>({id,label,min,max,step,value,unit}),choice=(id,label,options,value)=>({id,label,options,value});
 const years=()=>a('years','Remaining horizon',0,15,.5,5,'years'),rate=()=>a('rate','Discount rate',0,10,.5,3,'%'),fund=()=>a('funding','Net funding spread',0,500,10,120,'bps');
 const bars=(labels,values)=>labels.map((label,i)=>({label,value:values[i],color:values[i]<0?'#b57e3e':['#285e46','#83ab74','#587e8e','#c9984d'][i%4]}));
 const sources={credit:['https://www.bis.org/basel_framework/chapter/MAR/50.htm','Basel MAR50 · CVA value and CVA risk capital'],framework:['https://arxiv.org/abs/1501.05893','Bichuch, Capponi & Sturm · XVA framework'],funding:['https://arxiv.org/abs/1603.03012','Albanese & Crépey · capital and funding'],margin:['https://arxiv.org/abs/1405.0508','Green & Kenyon · initial margin funding'],capital:['https://arxiv.org/abs/1405.0515','Green, Kenyon & Dennis · KVA'],correction:['https://arxiv.org/abs/1807.10924','Kenyon & Green · corrected KVA and MVA framework'],clearing:['https://arxiv.org/abs/1506.08595','Armenti & Crépey · central clearing'],tax:['https://arxiv.org/abs/1407.3201','Kenyon & Green · credit warehousing and tax'],liquidity:['https://arxiv.org/abs/1210.5046','Crépey et al. · credit, liquidity and replacement cost'],prudent:['https://eur-lex.europa.eu/legal-content/EN/ALL/?uri=CELEX%3A32016R0101','EU 2016/101 · prudent valuation and AVAs']};
 const line=(name,color,fn,T)=>({name,color,data:Array.from({length:41},(_,i)=>{const t=T*i/40;return[t,fn(t)]})});
 const L=[];window.XVA_LESSONS=L;
 function add(l){L.push({stage:'02 · The core adjustments',simpleTitle:'The idea, simply',key:'All money values are £m. Positive charges reduce value; a benefit is identified explicitly. The formula is specific to this teaching example.',notes:[],...l});}
 add({id:'overview',name:'The XVA value bridge',stage:'01 · Start with intuition',title:'A clean price is only the beginning',intro:'A derivative is a promise, a stream of cash needs, and a commitment of capital. Move the controls to see the economic costs behind the quoted price.',chart:'Charges and benefits relative to clean value (£m)',inputs:[a('exposure','Future exposure level',0,50,1,20),a('collateral','Exposure covered by collateral',0,100,5,50,'%'),a('hazard','Counterparty hazard rate',0,10,.5,2,'% / year'),fund(),a('im','Segregated initial margin',0,15,.5,3),a('capital','Capital committed',0,10,.5,2),years()],challenge:'Increase collateral, then increase initial margin. Why does one cost fall while another can rise?',formula:'Illustrative economic value = clean value − CVA + DVA − FVA − MVA − KVA',simple:'Imagine quoting a delivery price. The item has a price, but the promise also has a chance of non-payment and needs financing. XVA makes those extra economics visible. Each bar asks a different question: who might fail, who supplies cash, and who commits capital?',scope:'A deliberately additive, constant-balance cost bridge with clean value £10m, discount rate 3%, recovery 40%, own hazard 1%, negative exposure 35% of positive exposure and annual capital hurdle 8%. Independent unilateral CVA/DVA. FVA uses an illustrative liquidity-only spread excluding the own-default component. ColVA is zero because collateral earns the clean benchmark rate. This is not a universal fair-value formula; coupled replication, first-to-default and feedback effects are omitted.',sources:[sources.framework,sources.funding,sources.correction],compute(s){const r=M.bridge(s);return {stats:[['Clean value',m(10)],['Net adjustment',m(-r.cost)],['Illustrative economic value',m(10-r.cost)]],bars:bars(['CVA cost','DVA benefit','FVA cost','MVA cost','KVA cost'],[-r.cva,r.dva,-r.fva,-r.mva,-r.kva]),headers:['Component','Value impact','What it pays for'],rows:[['CVA',m(-r.cva),'Counterparty default loss'],['DVA',m(r.dva),'Own-default benefit on liabilities'],['FVA',m(-r.fva),'Liquidity spread on unsecured funding'],['MVA',m(-r.mva),'Funding segregated initial margin'],['KVA',m(-r.kva),'Return required on committed capital']],explanation:`At ${s.collateral}% collateral coverage, unsecured exposure is ${m(s.exposure*(1-s.collateral/100))}. The net adjustment is ${m(-r.cost)}. Margin principal is not itself a loss: its funding cost accumulates while it is tied up.`,note:'Bars are signed value contributions: left is a cost; right is a benefit. These simplified inputs do not make the result an accounting fair value.'};}});
 add({id:'exposure',name:'Exposure and netting',stage:'01 · Start with intuition',title:'Being owed money is different from trading a large notional',intro:'Combine two trade values before taking the positive part. The legal netting arrangement determines whether an amount you owe can offset an amount owed to you.',chart:'From trade values to an unsecured claim (£m)',inputs:[a('tradeA','Trade A future value',-40,40,1,25),a('tradeB','Trade B future value',-40,40,1,-20),a('collateral','Collateral received for A / net set',0,30,1,2),choice('netting','Close-out arrangement',[['yes','One enforceable netting set'],['no','Separate sets; collateral allocated to A']],'yes')],challenge:'Keep the trades unchanged and switch the legal arrangement. Does the economic hedge guarantee the same credit exposure?',formula:'One set: E = max(VA + VB − C, 0)\nSeparate sets: E = max(VA − C, 0) + max(VB, 0)',simple:'You owe one shop £20 and a different shop owes you £25. You cannot assume the bills cancel. An enforceable netting agreement creates the right to settle a single balance. In a portfolio simulation this calculation happens in every future market state.',scope:'One deterministic future state; collateral is enforceable cash, applied only to Trade A when the trades are separated. No collateral return claim, default timing or margin gap is modelled. These are scenario exposures, not expected exposure profiles.',sources:[sources.credit,sources.framework],compute(s){const gross=Math.max(s.tradeA,0)+Math.max(s.tradeB,0),e=s.netting==='yes'?Math.max(s.tradeA+s.tradeB-s.collateral,0):Math.max(s.tradeA-s.collateral,0)+Math.max(s.tradeB,0);return {stats:[['Gross positive claims',m(gross)],['Unsecured claim',m(e)],['Reduction',m(gross-e)]],bars:bars(['Trade A','Trade B','Gross claims','After agreements'],[s.tradeA,s.tradeB,gross,e]),headers:['Step','Amount'],rows:[['Trade A',m(s.tradeA)],['Trade B',m(s.tradeB)],['Collateral applied',m(s.collateral)],['Final positive exposure',m(e)]],explanation:`The claim at risk is ${m(e)}. ${s.netting==='yes'?'The values offset inside the same legal set before collateral is deducted.':'The payable in one set cannot cancel the receivable in another.'}`,note:'The same portfolio can have very different XVA under different enforceable agreements.'};}});
 for(const own of [false,true])add({id:own?'dva':'cva',name:own?'DVA · own credit':'CVA · counterparty credit',title:own?'Why can your own worsening credit create a valuation gain?':'What is a risky promise worth today?',intro:own?'A liability may be worth less when the payer may not pay in full. From the bank’s perspective this is a DVA benefit, not cash earned from healthy trading.':'CVA is the present value of expected counterparty default losses. It depends on future exposure, the timing of default, and what can be recovered.',chart:own?'Cumulative own-default benefit over the horizon':'Cumulative counterparty default loss over the horizon',inputs:[a('exposure',own?'Expected negative exposure magnitude':'Expected positive exposure',0,100,1,20),a('hazard',own?'Own hazard rate':'Counterparty hazard rate',0,15,.5,2,'% / year'),a('recovery','Recovery at default',0,100,5,40,'%'),years(),rate()],challenge:own?'Increase your own hazard rate. Explain why the accounting benefit would not be a sensible business objective.':'Set recovery to 100%, then hazard to zero. What makes the expected loss disappear in each case?',formula:`${own?'DVA':'CVA'} = E × (1 − R) × λ × [1 − exp(−(r + λ)T)] / (r + λ)`,simple:own?'If you owe £100, a creditor values that promise below £100 when you might fail. The same change reduces the value of your liability. It does not create a customer payment to you, repair your funding access, or compensate shareholders for distress.':'Think of a claim as a payment that may be interrupted. You only lose the unrecovered amount when default happens while the claim exists. Discounting translates those possible future losses into today’s value.',scope:'Unilateral illustration with constant expected exposure, recovery, hazard and continuously compounded discount rate, independent market and credit risk. DVA uses the magnitude of negative exposure. Combining these unilateral values omits first-to-default effects. Hazard is an instantaneous annual intensity, not a cumulative default probability.',sources:[sources.framework,sources.credit],compute(s){const r=M.credit(s.exposure,s.hazard,s.recovery,s.years,s.rate),label=own?'DVA benefit':'CVA charge';return {stats:[[label,m(r.value)],['Cumulative default probability',p(r.pd)],['Value impact',m((own?1:-1)*r.value)]],series:[line(label+' (£m)',own?'#83ab74':'#285e46',t=>M.credit(s.exposure,s.hazard,s.recovery,t,s.rate).value,s.years)],xlabel:'Years',headers:['Input / result','Amount','Meaning'],rows:[['Exposure',m(s.exposure),own?'Magnitude of what we may owe':'What the counterparty may owe'],['Loss given default',p(1-s.recovery/100),'Unrecovered share'],['Cumulative PD',p(r.pd),'1 − exp(−hazard × years)'],[label,m(r.value),'Discounted expected default amount']],explanation:`${label} is ${m(r.value)} with a ${p(r.pd)} cumulative default probability. ${own?'A larger benefit reflects a weaker promise to creditors; it is not spendable cash.':'A higher exposure or lower recovery raises the loss even without an actual default.'}`,note:'CVA value differs from SA-CVA capital. Regulatory CVA excludes the firm’s own-default benefit.'};}});
 add({id:'fva',name:'FVA · cost and benefit',title:'Who supplies the cash while the trade is alive?',intro:'A profitable position may still need cash today. Funding cost adjustment (FCA) pays for borrowing; funding benefit adjustment (FBA) reflects reusable cash that avoids borrowing.',chart:'Borrowing cost versus reusable-cash benefit (£m)',inputs:[a('need','Cash that must be borrowed',0,50,1,20),a('surplus','Reusable cash surplus',0,50,1,5),a('borrow','Borrowing liquidity spread',0,500,10,150,'bps'),a('lend','Avoided funding spread on surplus',0,300,10,50,'bps'),years()],challenge:'Make borrowing and avoided-funding spreads different. Why does reversing a trade not necessarily reverse its FVA?',formula:'FCA = funding need × borrowing spread × annuity\nFBA = reusable surplus × benefit spread × annuity\nFVA charge = FCA − FBA',simple:'A business can own a valuable asset and still need a loan to make today’s payment. Derivatives have the same timing problem. Cash receipts help only when they are actually available for reuse; segregated initial margin is not spare treasury cash.',scope:'Constant expected borrowing and reusable-surplus balances in separate funding pools or states, discounted at 3%. No automatic netting between pools. Spreads represent a liquidity component excluding own-default compensation. Funding strategy, collateral reuse and DVA/FVA overlap need one consistent framework in a real valuation.',sources:[sources.funding,sources.framework],compute(s){const r=M.funding(s.need,s.surplus,s.borrow,s.lend,s.years);return {stats:[['FCA',m(r.fca)],['FBA',m(r.fba)],['Net funding charge',m(r.net)]],bars:bars(['FCA cost','FBA benefit','Net value impact'],[-r.fca,r.fba,-r.net]),headers:['Cash stream','Annual amount','Present value'],rows:[['Borrowing cost',m(s.need*s.borrow/10000),m(r.fca)],['Avoided funding benefit',m(s.surplus*s.lend/10000),m(r.fba)],['Net charge','Cost minus benefit',m(r.net)]],explanation:`Funding adds a ${r.net>=0?'cost':'benefit'} of ${m(Math.abs(r.net))}. An extra pound of cash does not have the same economics if it is trapped, reusable, or borrowed at a different spread.`,note:'FBA is a financing benefit under the assumed policy, not an automatic benefit on every negative trade value.'};}});
 add({id:'colva',name:'ColVA · collateral interest',title:'Collateral can protect the claim and change its price',intro:'Cash collateral earns interest. If its contractual remuneration differs from the clean discounting benchmark, the difference changes the trade’s economics.',chart:'Collateral carry relative to the clean benchmark (£m)',inputs:[a('collateral','Signed collateral: positive = received',-30,30,1,10),a('benchmark','Clean benchmark rate',0,8,.25,3,'%'),a('remuneration','Collateral remuneration rate',0,8,.25,2,'%'),years()],challenge:'Reverse the sign of collateral. Then match the two interest rates. Explain both changes.',formula:'ColVA value contribution = C × (rbenchmark − rcollateral) × annuity(rbenchmark, T)',simple:'Suppose you hold reusable cash collateral and can earn the benchmark rate while paying the agreed collateral rate to its owner. The difference is carry. When you post collateral, the direction reverses. If the clean valuation already uses the contractual collateral rate, charging this difference again would repeat the adjustment.',scope:'Constant signed reusable cash collateral; positive means received. Benchmark reinvestment and posting opportunity cost are assumed. No haircut, collateral-currency option, FX basis, substitution option or segregation. A benchmark-discounted clean value is required for this illustrative ColVA.',sources:[sources.framework,sources.liquidity],compute(s){const annual=s.collateral*(s.benchmark-s.remuneration)/100,v=annual*M.annuity(s.benchmark/100,s.years);return {stats:[['Rate difference',(s.benchmark-s.remuneration).toFixed(2)+'%'],['Annual carry',m(annual)],['ColVA value impact',m(v)]],series:[line('Accumulated ColVA (£m)','#587e8e',t=>annual*M.annuity(s.benchmark/100,t),s.years)],xlabel:'Years',headers:['Step','Value'],rows:[['Signed collateral',m(s.collateral)],['Rate mismatch',(s.benchmark-s.remuneration).toFixed(2)+' percentage points'],['Annual carry',m(annual)],['Discounted carry',m(v)]],explanation:`The collateral ${v>=0?'adds':'removes'} ${m(Math.abs(v))} relative to the benchmark. ${s.benchmark===s.remuneration?'Matching rates remove the carry difference.':'The sign depends on both who posts the cash and which rate is higher.'}`,note:'ColVA is a signed contribution here. Definitions and the choice of clean valuation differ between frameworks.'};}});
 add({id:'mva',name:'MVA · initial margin',title:'Returned money can still be expensive to tie up',intro:'Initial margin is a buffer against future market moves during close-out. Even when it is returned in full, financing that buffer can be costly.',chart:'Margin principal versus its funding cost (£m)',inputs:[a('im','Base initial margin',0,20,.5,5),a('stress','Margin scaling factor',.5,3,.1,1,'×'),fund(),years()],challenge:'Double initial margin without changing default risk. Does the margin principal become a loss?',formula:'MVA charge = posted IM × net funding spread × annuity(3%, T)',simple:'A refundable rental deposit is not a rental expense, but borrowing the deposit creates interest expense. MVA applies that distinction to initial margin. Variation margin settles current exposure; initial margin is a buffer for possible future changes and is often segregated.',scope:'Posted segregated IM is constant at base IM × scaling factor. The funding spread is already net of IM remuneration. It is excluded from the FVA funding balance. No SIMM, CCP margin model, future IM simulation, survival weighting or feedback. The scale slider is a scenario assumption, not a prescribed stress multiplier.',sources:[sources.margin,sources.correction],compute(s){const im=s.im*s.stress,cost=im*s.funding/10000*M.annuity(.03,s.years);return {stats:[['Posted IM principal',m(im)],['Annual funding cost',m(im*s.funding/10000)],['MVA charge',m(cost)]],bars:bars(['IM principal','MVA cost'],[im,cost]),headers:['Step','Amount','Interpretation'],rows:[['Posted initial margin',m(im),'Returned principal assumed'],['Net funding spread',s.funding+' bps','After remuneration'],['MVA',m(cost),'PV of financing expense']],explanation:`The ${m(im)} margin balance generates a ${m(cost)} funding charge over ${s.years} years. Funding becomes free in this model when the net spread is zero, even though margin is still posted.`,note:'The two bars compare a balance and a present-value expense; they must not be added together.'};}});
 add({id:'kva',name:'KVA · committed capital',title:'Capital is a cushion; KVA is the price of providing it',intro:'Shareholders commit a loss-absorbing buffer and require a return for doing so. KVA translates that required future return into a present economic cost.',chart:'How the required capital return accumulates (£m)',inputs:[a('capital','Capital allocated to the trade',0,20,.5,3),a('hurdle','Annual required return on capital',0,25,.5,10,'%'),years(),rate()],challenge:'Keep allocated capital fixed and reduce the return requirement. What falls, and what remains committed?',formula:'KVA cost proxy = K × h × annuity(r, T)',simple:'Owning a fire extinguisher is different from paying someone to keep it available. Capital is the buffer that absorbs losses; KVA represents remuneration for supplying that buffer over time. KVA is not the capital requirement itself and is not a substitute for calculating regulatory capital.',scope:'Constant allocated capital and a gross annual required-return charge, discounted at the selected rate. This is a discounted cash-cost proxy, not a semi-replication KVA formula. Capital relief, retained earnings, tax, capital used for funding, survival and endogenous discounting are omitted.',sources:[sources.capital,sources.correction],compute(s){const annual=s.capital*s.hurdle/100,v=annual*M.annuity(s.rate/100,s.years);return {stats:[['Capital balance',m(s.capital)],['Required annual return',m(annual)],['KVA cost proxy',m(v)]],series:[line('Cumulative remuneration PV (£m)','#285e46',t=>annual*M.annuity(s.rate/100,t),s.years)],xlabel:'Years of commitment',headers:['Quantity','Amount','Meaning'],rows:[['K',m(s.capital),'Loss-absorbing resource'],['h',s.hurdle+'%','Annual required return'],['K × h',m(annual),'Annual remuneration'],['KVA proxy',m(v),'Discounted remuneration over time']],explanation:`Committing ${m(s.capital)} requires ${m(annual)} each year under this hurdle assumption. Its discounted cost is ${m(v)}. A smaller KVA does not by itself mean the regulatory capital requirement fell.`,note:'Link to the FRTB and SA-CVA modules to study capital calculations; this applet starts from an assumed capital allocation.'};}});
 add({id:'wrong-way',name:'Wrong-way risk',stage:'03 · Connect the adjustments',title:'What if the biggest claim arrives at the worst moment?',intro:'Average exposure and average default probability do not tell the whole story. Make default more likely in the high-exposure state while keeping the average probability fixed.',chart:'Exposure-default alignment and expected loss (£m)',inputs:[a('quiet','Exposure in the quiet state',0,50,1,5),a('stress','Exposure in the stressed state',0,100,1,30),a('pd','Average one-period default probability',0,30,1,5,'%'),a('dependence','Shift default toward stressed state',-100,100,10,60,'%'),a('recovery','Recovery',0,100,5,40,'%')],challenge:'Make the exposures equal. Can reallocating default probability between the states still change the loss?',formula:'Expected loss = ½ × Equiet × PDquiet × LGD + ½ × Estress × PDstress × LGD\nPDquiet = PD × (1 − d); PDstress = PD × (1 + d)',simple:'An umbrella is least useful if it breaks precisely when it rains. Similarly, low average counterparty risk can hide expensive dependence when your largest receivable appears exactly when the payer is weakest. Wrong-way risk describes this alignment, not merely a high default probability.',scope:'Two equally likely states over one period, with no discounting. Slider bounds keep conditional probabilities between 0% and 60%. The dependence slider redistributes default probability, not a statistical correlation coefficient. This is a joint-state loss illustration, not a calibrated credit-market model.',sources:[sources.credit,sources.framework],compute(s){const r=M.wrongWay(s.quiet,s.stress,s.dependence,s.pd,s.recovery);return {stats:[['Independent loss',m(r.independent)],['Linked loss',m(r.linked)],['Dependence effect',m(r.linked-r.independent)]],bars:bars(['Independent loss','Linked loss'],[r.independent,r.linked]),headers:['State','Exposure','Conditional PD','Loss contribution'],rows:[['Quiet',m(s.quiet),p(r.quietPD),m(.5*s.quiet*r.quietPD*(1-s.recovery/100))],['Stressed',m(s.stress),p(r.stressPD),m(.5*s.stress*r.stressPD*(1-s.recovery/100))]],explanation:`The average default probability stays at ${s.pd}%, but joint-state expected loss is ${m(r.linked)}. ${r.linked>r.independent?'Default is more aligned with large claims.':r.linked<r.independent?'Default is less aligned with large claims.':'There is no net dependence effect at these settings.'}`,note:'The label “stressed” does not guarantee higher exposure: the actual input values determine whether the alignment is wrong-way or right-way.'};}});
 add({id:'incremental',name:'Incremental XVA',stage:'03 · Connect the adjustments',title:'The same trade can cost less inside a different portfolio',intro:'A trade that offsets an existing claim can release credit and funding costs. Compare its standalone cost with the change it creates in an existing netting set.',chart:'Standalone, portfolio and incremental cost (£m)',inputs:[a('existing','Existing future portfolio value',-40,40,1,20),a('trade','New trade future value',-40,40,1,-10),a('hazard','Counterparty hazard',0,10,.5,2,'% / year'),fund(),years()],challenge:'Start with a positive portfolio and add a negative trade. Why can an incremental charge be negative?',formula:'Incremental cost = cost(existing + new) − cost(existing)\nCost(V) = unilateral CVA(max(V,0)) + funding cost(max(V,0))',simple:'Adding a coat to an empty suitcase uses space. Replacing a bulky coat with a smaller one can free space. A trade’s effect on the whole portfolio similarly differs from its standalone footprint. XVA pricing therefore depends on the netting set, existing hedges and agreements.',scope:'One constant deterministic future value, same enforceable netting set, no collateral. A deliberately narrow CVA-plus-liquidity-funding proxy, recovery 40% and discount rate 3%. Omits DVA, capital, IM, multi-state exposure and allocation policy. Negative incremental cost is a release in this proxy, not guaranteed trade profit.',sources:[sources.framework,sources.funding],compute(s){const cost=v=>M.credit(Math.max(v,0),s.hazard,40,s.years).value+M.funding(Math.max(v,0),0,s.funding,0,s.years).net,before=cost(s.existing),after=cost(s.existing+s.trade),standalone=cost(s.trade),inc=after-before;return {stats:[['Standalone cost',m(standalone)],['Incremental cost',m(inc)],['Portfolio after trade',m(after)]],bars:bars(['Before trade','After trade','Standalone','Incremental'],[before,after,standalone,inc]),headers:['Portfolio','Positive exposure','CVA + funding cost'],rows:[['Existing',m(Math.max(s.existing,0)),m(before)],['New trade alone',m(Math.max(s.trade,0)),m(standalone)],['Combined',m(Math.max(s.existing+s.trade,0)),m(after)],['Incremental','Difference',m(inc)]],explanation:`The new trade has standalone cost ${m(standalone)}, but changes this portfolio’s cost by ${m(inc)}. ${inc<0?'It releases an existing exposure and funding charge.':'Its incremental charge depends on what was already in the set.'}`,note:'Incremental and allocated XVA answer different questions. Allocation among all trades requires a separate policy.'};}});
 add({id:'clearing',name:'CCVA · clearing economics',stage:'04 · Beyond the core',title:'Clearing changes the cost mix; it does not make risk disappear',intro:'Clearing can reduce bilateral credit exposure while increasing margin, fees and default-fund commitments. Compare two stylised routes for the same activity.',chart:'Bilateral versus cleared annual-cost present values (£m)',inputs:[a('bilateral','Bilateral annual credit cost proxy',0,1,.05,.25),a('im','Cleared initial margin',0,30,1,8),fund(),a('df','Default-fund contribution',0,10,.5,1),a('fees','Annual clearing fee',0,.5,.01,.05),years()],challenge:'Lower the bilateral credit cost and raise cleared margin. Is clearing always the cheaper route?',formula:'Cleared cost proxy = (IM funding + DF funding + assumed DF loss + capital remuneration + fees) × annuity\nBilateral comparator = assumed annual credit cost × annuity',simple:'A clearing house replaces many bilateral promises with a managed network and a default waterfall. That can improve risk management, but a member must still finance margins, contribute to mutual protection and pay for capital and services. CCVA is an umbrella over those costs, not an extra charge to add to them again.',scope:'Clearing-member example. DF funding uses the selected net spread; illustrative annual DF loss is 1% of its balance and capital remuneration is 8% on assumed capital of 20% of IM plus DF. Discount rate 3%. Bilateral input is an assumed annual credit-cost equivalent only. No CCP-calibrated default waterfall, client-clearing model or matched portfolio comparison.',sources:[sources.clearing,sources.margin],compute(s){const A=M.annuity(.03,s.years),im=s.im*s.funding/10000*A,df=s.df*s.funding/10000*A,loss=s.df*.01*A,k=(s.im*.2+s.df)*.08*A,fees=s.fees*A,total=im+df+loss+k+fees,b=s.bilateral*A;return {stats:[['Bilateral proxy',m(b)],['Cleared proxy',m(total)],['Difference',m(total-b)]],bars:bars(['Bilateral proxy','IM funding','DF funding','DF loss proxy','Capital cost','Fees','Cleared total'],[b,im,df,loss,k,fees,total]),headers:['Cleared component','PV','Assumption'],rows:[['IM funding',m(im),'Segregated balance × spread'],['DF funding',m(df),'Contribution × spread'],['Mutualised loss',m(loss),'1% annual loss proxy'],['Capital remuneration',m(k),'8% on assumed capital'],['Fees',m(fees),'Annual fee discounted']],explanation:`Cleared costs total ${m(total)} in this assumed scenario. ${total>b?'The margin, capital and service commitments exceed the bilateral credit-cost proxy.':'The assumed cleared costs are below the bilateral credit-cost proxy.'} Change the assumptions to understand the trade-off.`,note:'This is a cost anatomy, not a recommendation to clear or an estimate of an actual CCP’s risk.'};}});
 add({id:'reserves',name:'LVA, model risk and AVA',stage:'04 · Beyond the core',title:'How confident are you that the marked price can be realised?',intro:'An exit cost, a model reserve and a prudent valuation adjustment solve different problems. Change the uncertainty and see what remains after an existing reserve covers the same risk.',chart:'From model mark to prudent value for an asset (£m)',inputs:[a('mark','Unadjusted asset mark',0,30,1,10),a('exit','Assumed liquidity / exit cost',0,3,.1,.4),a('model','Assumed model uncertainty allowance',0,3,.1,.6),a('reserve','Existing same-risk accounting reserve',0,5,.1,.3)],challenge:'Increase the existing reserve without changing the prudent benchmark. Why should the additional adjustment shrink?',formula:'Teaching prudent benchmark = mark − exit allowance − model allowance\nFair value after reserve = mark − existing reserve\nIllustrative additional shortfall = max(exit allowance + model allowance − existing reserve, 0)',simple:'A model mark is a best estimate under a chosen model. An executable exit price may differ because of bid–offer costs or uncertainty. A reserve already recognised for the same issue should not be deducted twice. Prudential AVA addresses an additional prudence gap; it is distinct from the funding XVA family.',scope:'Single asset and assumed additive, non-overlapping allowances. This is not an EU or PRA AVA calculation: it omits prescribed category methods, confidence calibration, eligibility, aggregation and exemptions. LVA sometimes means liquidity funding cost within FVA; here “exit cost” is used explicitly. Model risk reserves are not MVA, which means margin valuation adjustment in this module.',sources:[sources.prudent,sources.liquidity],compute(s){const fair=s.mark-s.reserve,prudent=s.mark-s.exit-s.model,ava=Math.max(fair-prudent,0);return {stats:[['After existing reserve',m(fair)],['Toy prudent benchmark',m(prudent)],['Additional shortfall',m(ava)]],bars:bars(['Model mark','After reserve','Prudent benchmark','Extra shortfall'],[s.mark,fair,prudent,ava]),headers:['Quantity','Amount','Purpose'],rows:[['Exit allowance',m(s.exit),'Assumed executable-price cost'],['Model allowance',m(s.model),'Assumed model uncertainty'],['Existing reserve',m(s.reserve),'Already recognised for same risks'],['Additional shortfall',m(ava),'Residual gap only']],explanation:`The extra shortfall is ${m(ava)} after recognising the ${m(s.reserve)} same-risk reserve. These are assumed allowances, not a regulatory calibration. AVA concerns prudential valuation; it is not another funding charge.`,note:'Acronyms are context-dependent: FVA may also mean “fair value adjustment” in reporting, and LVA is not always a standalone add-on.'};}});
 add({id:'tax',name:'TVA · tax and terminology',stage:'04 · Beyond the core',title:'A required after-tax return needs a larger pre-tax amount',intro:'Tax can change the economics of providing capital and bearing risk. Explore a simple gross-up while keeping tax valuation separate from a full tax-aware XVA model.',chart:'After-tax target and illustrative tax gross-up (£m)',inputs:[a('target','Annual after-tax return target',0,2,.05,.3),a('tax','Effective tax rate',0,50,1,25,'%'),years()],challenge:'Set tax to zero. Then raise it while holding the after-tax target fixed. Who needs to supply the difference?',formula:'Pre-tax return = target / (1 − tax rate)\nTax cost proxy = [pre-tax return − target] × annuity(3%, T)',simple:'If a provider needs to keep a certain amount after tax, charging exactly that amount before tax will not meet the target. A gross-up closes this arithmetic gap. A full tax valuation model also considers the timing and treatment of profits and losses, including whether tax benefits can actually be used.',scope:'Deterministic annual return target with immediately payable proportional tax, discount rate 3% and no deductions or loss credits. This is a tax-cost intuition, not a jurisdiction-specific TVA calculation. Do not add this tax gross-up if KVA already includes the same pre-tax remuneration. TVA can mean Tax Valuation Adjustment or, in other research, Total Valuation Adjustment.',sources:[sources.tax,sources.liquidity],compute(s){const pretax=s.target/(1-s.tax/100),A=M.annuity(.03,s.years),tax=(pretax-s.target)*A;return {stats:[['Annual pre-tax requirement',m(pretax)],['Annual retained target',m(s.target)],['Tax cost PV proxy',m(tax)]],bars:bars(['Retained target PV','Tax gross-up PV','Pre-tax total PV'],[s.target*A,tax,pretax*A]),headers:['Quantity','Annual amount','Present value'],rows:[['After-tax target',m(s.target),m(s.target*A)],['Tax gross-up',m(pretax-s.target),m(tax)],['Pre-tax requirement',m(pretax),m(pretax*A)]],explanation:`Keeping ${m(s.target)} each year after ${s.tax}% tax requires ${m(pretax)} before tax in this example. The tax gross-up has present value ${m(tax)}.`,note:'Before comparing XVA figures, agree the perspective, clean-price convention, definitions, tax treatment and which costs are already included.'};}});
})();
